import express from 'express';
import { and, eq, sql } from "drizzle-orm";
import { getDbConnection } from "../db/connection";
import { instructorCourses } from "../db/models/instructor_courses";
import { studentCourses } from "../db/models/student_courses";
import { get } from 'http';

const router = express.Router()

  /**
   * @openapi
   * /api/instructor/credit-hours:
   *   get:
   *     summary: Retrieve total generated credit hours for an instructor in a specific term and year.
   *     description: >
   *       Calculates the total credit hours generated by an instructor by summing the stored course_hours from student enrollments.
   *       The calculation filters by instructor, term, and year, and relies on matching records in the instructor_courses
   *       and student_courses tables.
   *     parameters:
   *       - in: query
   *         name: instructorId
   *         required: true
   *         schema:
   *           type: string
   *         description: The unique identifier of the instructor.
   *       - in: query
   *         name: termCode
   *         required: true
   *         schema:
   *           type: string
   *         description: The term code for which to calculate credit hours.
   *       - in: query
   *         name: year
   *         required: true
   *         schema:
   *           type: integer
   *         description: The year for which to calculate credit hours.
   *     responses:
   *       200:
   *         description: Total generated credit hours successfully calculated.
   *         content:
   *           application/json:
   *             schema:
   *               type: object
   *               properties:
   *                 totalCreditHours:
   *                   type: number
   *                   description: The sum of credit hours generated by the instructor.
   *                   example: 90
   *       400:
   *         description: Bad Request - missing required query parameters.
   *         content:
   *           application/json:
   *             schema:
   *               type: object
   *               properties:
   *                 error:
   *                   type: string
   *                   example: "instructorId, termCode, and year are required."
   *       500:
   *         description: Internal Server Error.
   *         content:
   *           application/json:
   *             schema:
   *               type: object
   *               properties:
   *                 error:
   *                   type: string
   *                   example: "Internal server error"
   */
  .get('/credit-hours', async (req: any, res: any) => {
      const dbConnectionInstance = await getDbConnection();
      const db = dbConnectionInstance.orm;
    const { instructorId, termCode, year } = req.query;

    // Validate query parameters
    if (!instructorId || !termCode || !year) {
      return res
        .status(400)
        .json({ error: "instructorId, termCode, and year are required." });
    }

    // Convert year from string to number
    const yearInt = parseInt(year as string, 10);
    if (isNaN(yearInt)) {
      return res
        .status(400)
        .json({ error: "Year must be a valid integer." });
    }

    try {
      const yearInt = parseInt(year as string, 10);

      const instructorCoursesResult = await db
        .select({
          totalCreditHours: sql<number>`COALESCE(SUM(${studentCourses.course_hours}), 0)`
        })
        .from(instructorCourses)
        .leftJoin(
          studentCourses,
          and(
            eq(instructorCourses.course_subject, studentCourses.course_subject),
            eq(instructorCourses.course_number, studentCourses.course_number),
            eq(instructorCourses.course_suffix, studentCourses.course_suffix),
            eq(instructorCourses.term, studentCourses.term), // adjust as needed
            eq(instructorCourses.year, studentCourses.year)
          )
        )
        .where(
          and(
            eq(instructorCourses.user_id, instructorId as string),
            eq(instructorCourses.term, termCode as string),
            eq(instructorCourses.year, yearInt)
          )
        );

      return res.json(instructorCoursesResult[0]);
    } catch (error) {
      console.error("Error fetching credit hours:", error);
      return res.status(500).json({ error: "Internal server error" });
    }
  });

export default router;